        total: z.number().int().nonnegative(),
        includedInStats: z.number().int().nonnegative(),
        aborted: z.number().int().nonnegative(),
        abandoned: z.number().int().nonnegative(),
      })
      .strict(),
    slots: z.array(pasteSlotSchema),
  })
  .strict();

