  border-color: var(--warn);
}

.slot-header {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
}

.slot-title {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.slot-title label {
  font-size: 16px;
  font-weight: 560;
  color: var(--text);
}

.slot-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.slot-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px 12px;
  margin-bottom: 12px;
  font-size: 14px;
}

.meta-players {
  color: var(--text);
  overflow-wrap: anywhere;
}

.meta-detail {
  color: var(--muted);
  font-family: ui-monospace, monospace;
  font-size: 12px;
  overflow-wrap: anywhere;
}

.meta-excluded {
  padding: 2px 6px;
  border: 1px solid var(--line);
  border-radius: 4px;
  color: var(--muted);
  font-size: 12px;
}

textarea {
  display: block;
  width: 100%;
  box-sizing: border-box;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: var(--bg);
  color: var(--text);
  font-family: ui-monospace, monospace;
  font-size: 12px;
  line-height: 1.5;
  resize: vertical;
}

.slot-error {
  margin-top: 8px;
  color: var(--warn);
  font-size: 14px;
  max-width: none;
}

